{
  "case_id": "xsu_sg_005_work_capacity_scope",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret åbner med et generelt 'Nej' og lister alle syv punkter som ikke indgående. Det er forkert for kommunal arbejdsevnevurdering, som ifølge kilden ikke er målestokken, men heller ikke er et vurderingsled. Det er i øvrigt korrekt for de øvrige punkter. Det er dog en væsentlig unøjagtighed, at svaret ikke nævner, at tidligere og aktuelt erhvervsarbejde kan indgå. Svaret siger også, at vurderingen fokuserer på 'betydelig reducering', mens loven kræver 'meget betydelige begrænsninger'. Det er en juridisk afvigelse i tærsklen."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle fem kritiske elementer er dækket. Målestokken er erhvervsevne under uddannelse. Kommunal arbejdsevnevurdering, arbejdsprøvning, særlig arbejdspladsindretning, arbejdsgiverkontakt, studierelevans, lokale forhold og erhvervsevne efter uddannelse nævnes som ikke indgående. Dog er 'de ressourcer, personen har' og 'muligheden for at finde arbejde' ikke eksplicit gengivet. 'Lokale jobmuligheder' dækker dog stort set det sidste."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret behandler alle syv punkter i spørgsmålet direkte og uden irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen kilde, hverken lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så støtten kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en tærskel, 'betydelig reducering', der ikke svarer til kilderne. Disse kræver 'meget betydelige begrænsninger'. Derudover er udsagnet om, at kommunal arbejdsevnevurdering 'ikke indgår', ikke understøttet i den form. Kilden siger blot, at erhvervsevnen ikke kan sammenlignes med kommunernes arbejdsevnevurdering."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer ikke 'meget betydelige' som tærskel, men skriver 'betydelig'. Det udelader også, at tidligere eller nuværende arbejde indgår, og at vurderingen bygger på funktionsnedsættelsens art og grad."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Forklaringen er intern konsistent: vurderingen fokuserer på funktionsnedsættelsens indvirkning på evnen til erhvervsarbejde under uddannelse, og de opregnede punkter holdes uden for. Konklusionen følger af dette."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gør alle punkter absolut udelukkede med et samlet 'Nej'. Kilden skelner mellem, at kommunal arbejdsevnevurdering ikke er målestok, og at de øvrige punkter udtrykkeligt ikke indgår. Tærsklen 'betydelig reducering' svækker desuden modaliteten 'meget betydelige begrænsninger'."
    }
  },
  "xhaile_coverage": {
    "A15": {
      "label": "partial",
      "reason": "Svaret dækker, at arbejdsprøvning, indretning, arbejdsgiverkontakt, studierelevans, lokale forhold og erhvervsevne efter uddannelsen ikke indgår, og at vurderingen angår erhvervsevne under uddannelse. Det gengiver dog ikke kravet om 'meget betydelige begrænsninger' korrekt (skriver 'betydelig reducering'). Ordblindeeksemplet og pointen om, at der er flere typer erhvervsarbejde, og at man skal kunne varetage erhvervsarbejde med sine ressourcer, mangler. Svaret nævner heller ikke eksplicit vanskeligheder med at finde arbejde."
    }
  },
  "overall_notes": "Svaret har en korrekt kerne i opregningen af, hvad der ikke indgår, men det er upræcist på den kommunale arbejdsevnevurdering og på tærsklen. Det angiver ingen kilder, så C04 er not_met, og C05 og C06 er not_assessable."
}

